import{_ as s,E as r,h as l,c as d,b as e,f as a,H as n,w as c,a4 as p}from"./chunks/framework.B_fYP6Of.js";const y=JSON.parse('{"title":"Design patterns review","description":"An independent design-pattern review of retrieval adapters, stream notifications, and workflow ownership, with acceptance checks for each proposed abstraction.","frontmatter":{"title":"Design patterns review","description":"An independent design-pattern review of retrieval adapters, stream notifications, and workflow ownership, with acceptance checks for each proposed abstraction.","teaser":"Two tools may both offer search and still disagree about filters, ordering, or dropped results. An adapter earns its place by making those differences observable."},"headers":[],"relativePath":"reviews/design-patterns.md","filePath":"reviews/design-patterns.md"}'),u={name:"reviews/design-patterns.md"};function h(f,t,m,g,v,b){const i=r("LabArticleHeader"),o=r("LabScroll");return l(),d("div",null,[t[1]||(t[1]=e("h1",{id:"design-patterns-review",tabindex:"-1"},[a("Design patterns review "),e("a",{class:"header-anchor",href:"#design-patterns-review","aria-label":'Permalink to "Design patterns review"'},"​")],-1)),n(i),t[2]||(t[2]=e("p",null,[a("A retrieval adapter can hide a difference that matters to a reader. One implementation applies access filters while searching. Another returns its closest matches first and filters afterward. Both might satisfy a method named "),e("code",null,"search"),a(" and produce different evidence for the same question.")],-1)),t[3]||(t[3]=e("p",null,"This independent review applies published ideas from Erich Gamma, Richard Helm, Ralph Johnson, and John Vlissides to the draft. The authors did not participate in or endorse it. The application and its performance tests remain proposed.",-1)),t[4]||(t[4]=e("p",null,[a("The review favors explicit responsibilities and interchangeable mechanisms where the system has a real reason to vary. The authors' own retrospective emphasizes the consequences of patterns and their adaptation to different languages. This supports applying their intent through Rust traits, enums, functions, and composition rather than recreating a class hierarchy. "),e("a",{href:"https://www.informit.com/articles/article.aspx?p=1404056",target:"_blank",rel:"noreferrer"},"Gang of Four retrospective")],-1)),t[5]||(t[5]=e("h2",{id:"pattern-fit",tabindex:"-1"},[a("Pattern fit "),e("a",{class:"header-anchor",href:"#pattern-fit","aria-label":'Permalink to "Pattern fit"'},"​")],-1)),t[6]||(t[6]=e("p",null,[a("The following mappings are proposed applications to this system, rather than statements made by the book's authors about RAG. The original catalog includes these patterns. "),e("a",{href:"https://www.informit.com/store/design-patterns-elements-of-reusable-object-oriented-9780321770462",target:"_blank",rel:"noreferrer"},"Design Patterns catalog")],-1)),n(o,{kind:"table",label:"table for Pattern fit"},{default:c(()=>[...t[0]||(t[0]=[e("table",{tabindex:"0"},[e("thead",null,[e("tr",null,[e("th",{scope:"col"},"Pattern"),e("th",{scope:"col"},"Proposed application"),e("th",{scope:"col"},"Boundary and tradeoff")])]),e("tbody",null,[e("tr",null,[e("td",null,"Adapter"),e("td",null,"Convert SQLite/vector-extension, model-provider, broker, and document-parser interfaces into application contracts."),e("td",null,"Preserve provider-specific capabilities explicitly; converting types alone cannot make different behavior equivalent.")]),e("tr",null,[e("td",null,"Strategy"),e("td",null,"Select retrieval fusion, entity-resolution policy, or reranking algorithms."),e("td",null,"Introduce substitution where we will evaluate alternatives; keep a single straightforward implementation elsewhere.")]),e("tr",null,[e("td",null,"Observer"),e("td",null,"Notify local UI or service subscribers about run-state changes."),e("td",null,"Distributed pub/sub adds delivery, authorization, retention, and failure semantics beyond local notification.")]),e("tr",null,[e("td",null,"State"),e("td",null,"Constrain conversation runs and individual ingestion tasks to legal transitions."),e("td",null,"Separate run state from the independent readiness of text, vectors, graph, and augmentation.")]),e("tr",null,[e("td",null,"Composite"),e("td",null,"Traverse the tree-shaped parsed document: sections contain blocks and subsections."),e("td",null,"The workflow DAG has shared dependencies and requires node identities; treating it as a tree would duplicate work.")])])],-1)])]),_:1}),t[7]||(t[7]=p('<h2 id="p1-define-adapter-behavior-before-selecting-providers" tabindex="-1">P1: Define adapter behavior before selecting providers <a class="header-anchor" href="#p1-define-adapter-behavior-before-selecting-providers" aria-label="Permalink to &quot;P1: Define adapter behavior before selecting providers&quot;">​</a></h2><p>The separation of Rust use cases from Axum, NATS, SQLite, and model APIs is a strong starting point. Adapter is appropriate when an existing interface differs from the interface its client needs. <a href="https://www.informit.com/articles/article.aspx?p=1398600" target="_blank" rel="noreferrer">Original Adapter excerpt</a></p><p><strong>Finding:</strong> a generic <code>search()</code> or <code>generate()</code> interface would hide differences that affect correctness. Exact and approximate vector search have different recall properties. Metadata filtering may happen during candidate selection or afterward. Closing a model connection may stop local delivery while remote generation continues.</p><p><strong>Draft contract:</strong> retrieval requests carry corpus scope, access constraints, index revision, candidate limit, and deadline. Results carry canonical chunk IDs, document revisions, ranking method, and evidence locations. Adapters report supported filtering and search modes; unsupported requirements fail explicitly. Model adapters expose streaming, cancellation capability, partial-output behavior, and terminal errors. Domain code receives application records rather than SQL rows, broker messages, or provider SDK objects.</p><p><strong>Acceptance check.</strong> Give each adapter the same restrictive filter, deleted revision, deadline, and interrupted stream. For approximate retrieval, compare the returned eligible set with an exact baseline. The adapter must describe a difference a caller can observe or act on.</p><h2 id="p1-give-execution-state-one-authoritative-owner" tabindex="-1">P1: Give execution state one authoritative owner <a class="header-anchor" href="#p1-give-execution-state-one-authoritative-owner" aria-label="Permalink to &quot;P1: Give execution state one authoritative owner&quot;">​</a></h2><p><strong>Finding:</strong> callbacks from HTTP, broker delivery, timers, and workers can race. A notification must not independently advance workflow state, and an old attempt must not publish over a newer document revision.</p><p><strong>Draft contract:</strong> a run owner applies legal transitions from accepted through retrieval and generation to completion, cancellation, or failure. Terminal transitions are controlled by that owner. An ingestion orchestrator owns dependency completion and task attempts. Durable records identify source revision, input fingerprint, stage version, and attempt. Output publication checks the expected revision and ownership before committing.</p><p>Events identify run, attempt, sequence, and schema version. Duplicate events can be ignored safely. Cancellation is an authenticated command to the owner. Text, vector, graph, and augmentation readiness remain independent milestones.</p><p><strong>Acceptance check.</strong> Complete a run twice, request cancellation during generation, restart a worker, and replace a source revision. For each case ask someone to point to the authoritative final state and confirm how many artifacts were published. The record should explain every transition.</p><h2 id="p1-specify-notification-lifetime-and-delivery" tabindex="-1">P1: Specify notification lifetime and delivery <a class="header-anchor" href="#p1-specify-notification-lifetime-and-delivery" aria-label="Permalink to &quot;P1: Specify notification lifetime and delivery&quot;">​</a></h2><p><strong>Finding:</strong> calling every notification an Observer risks concealing loss and buffering behavior. A local subscriber, browser SSE connection, durable job consumer, and replay reader have different responsibilities.</p><p><strong>Draft contract:</strong> local subscriptions have explicit lifetimes and bounded buffers. Ordinary token delivery remains direct from the Rust run owner to the browser. NATS distributes cross-service events and selected durable work. Retained output replay, if required, has a defined cursor, retention window, and deduplication policy. A slow viewer catches up or reconnects according to policy; it cannot accumulate unlimited memory or stall unrelated viewers.</p><p><strong>Gate:</strong> verify unsubscribe cleanup, a stalled subscriber, reconnect overlap, missing sequence detection, and the chosen disconnect-versus-cancellation behavior.</p><h2 id="p2-keep-algorithm-substitution-narrow" tabindex="-1">P2: Keep algorithm substitution narrow <a class="header-anchor" href="#p2-keep-algorithm-substitution-narrow" aria-label="Permalink to &quot;P2: Keep algorithm substitution narrow&quot;">​</a></h2><p>Use Strategy for alternatives that share a declared result contract: rank fusion or an entity candidate scorer are useful examples. Keep ranking explanations, model versions, and resolution evidence with their outputs so changing a strategy remains auditable. Runtime selection can use a trait where needed; a function or enum is sufficient when the options are fixed.</p><p>Avoid a universal processor interface spanning parsers, retrievers, entity resolvers, and generators. Their inputs, failure modes, and resource requirements differ. A configuration switch should select a valid algorithm, rather than change hidden semantics behind a uniform method name.</p><h2 id="p2-model-the-dag-as-dependencies" tabindex="-1">P2: Model the DAG as dependencies <a class="header-anchor" href="#p2-model-the-dag-as-dependencies" aria-label="Permalink to &quot;P2: Model the DAG as dependencies&quot;">​</a></h2><p>The ETL workflow branches, joins, retries, and publishes versioned artifacts. Chain of Responsibility routes a request among potential handlers until one handles it; it does not describe this dependency execution model. <a href="https://www.informit.com/articles/article.aspx?p=1398601" target="_blank" rel="noreferrer">Original Chain of Responsibility excerpt</a></p><p>Use one durable orchestration authority, with bounded repair passes and explicit dependencies. Dagster versus Temporal remains an open decision. NATS delivery should not become a second independent workflow scheduler. Construct dependencies at application startup instead of accessing database connections or providers through global singletons.</p><p><strong>Acceptance:</strong> each abstraction must protect a demonstrated variation, ownership rule, or failure boundary. Measure its effect on latency and allocation when relevant; pattern coverage is not a project success metric.</p>',21))])}const k=s(u,[["render",h]]);export{y as __pageData,k as default};
